func verifiedStressComparison(t *testing.T, after bool) Report {
	t.Helper()
	var payload app.InventoryPayload
	if json.Unmarshal([]byte(stressReportLiteral), &payload) != nil {
		t.Fatal("literal report")
	}
	if after && json.Unmarshal([]byte(stressAdverseReportLiteral), &payload) != nil {
		t.Fatal("literal adverse report")
	}
	control, err := app.BuildInventoryPayload(inventory.NewSnapshot([]inventory.Component{inventory.NewComponent(inventory.ComponentBlock, "block:sda", map[string]string{"wwid": "fixture-exterior-disk", "model": "Fixture disk"})}), bytes.Repeat([]byte{0x39}, 32), "stress-fixture")
	if err != nil || !reflect.DeepEqual(control.Components, payload.Components) || control.SystemFingerprint != payload.SystemFingerprint {
		t.Fatal("literal independent HMAC control", err)
	}
	if err := app.ValidateCoverage(payload); err != nil {
		t.Fatal("valid coverage prerequisite", err)
	}
	raw, err := json.Marshal(payload)
	if err != nil {
		t.Fatal(err)
	}
	digest, err := bundle.ManifestDigest(raw, nil)
	if err != nil {
		t.Fatal(err)
	}
	id, generated := "11111111-1111-4111-8111-111111111111", "2026-01-01T00:00:00Z"
	if after {
		id, generated = "22222222-2222-4222-8222-222222222222", "2026-01-02T00:00:00Z"
	}
	key := ed25519.NewKeyFromSeed(bytes.Repeat([]byte{0x39}, ed25519.SeedSize))
	envelope := report.Envelope{Schema: report.EnvelopeSchemaV1, Product: product.Name, Version: product.Version, SessionID: id, GeneratedTime: generated, Payload: raw, ManifestDigest: digest, KeyID: "stress-fixture-signer"}
	if err := report.Sign(&envelope, key); err != nil {
		t.Fatal(err)
	}
	var archive bytes.Buffer
	if err := bundle.Write(&archive, raw, envelope, nil); err != nil {
		t.Fatal(err)
	}
	verified, err := bundle.Verify(bytes.NewReader(archive.Bytes()), int64(archive.Len()), report.Keyring{"stress-fixture-signer": key.Public().(ed25519.PublicKey)})
	if err != nil {
		t.Fatal("signed verification prerequisite", err)
	}
	var admitted app.InventoryPayload
	if json.Unmarshal(verified.InventoryJSON, &admitted) != nil {
		t.Fatal("verified inventory")
	}
	reference := ReportReference{SessionID: id, GeneratedTime: generated, SoftwareVersion: product.Version, SignerKeyID: "stress-fixture-signer", ManifestDigest: digest, SystemFingerprint: payload.SystemFingerprint, ComponentCount: 1}
	if verified.Envelope.SessionID != reference.SessionID || verified.Envelope.GeneratedTime != reference.GeneratedTime || verified.Envelope.ManifestDigest != reference.ManifestDigest || verified.Envelope.KeyID != reference.SignerKeyID || !bytes.Equal(verified.InventoryJSON, raw) {
		t.Fatal("complete signed references")
	}
	return Report{Reference: reference, Inventory: admitted}
}

func TestCPUStressSignedComparisonRetainsLiteralIdentityAndReferences(t *testing.T) {
	before, after := verifiedStressComparison(t, false), verifiedStressComparison(t, true)
	component := Component{Type: inventory.ComponentBlock, ID: "block:sda", IdentitySource: "wwid", Identity: "hmac-sha256:166124c103a9f3460b95772ccc28cbdb015931924d8d021ebed574af73df01af", IdentityConfidence: "durable", Attributes: []inventory.Attribute{{Name: "model", Value: "Fixture disk"}}}
	want := Result{Schema: "hhsoft.pc-tester.hardware-comparison/v1", Policy: "hhsoft.parts-swap.v1", Status: StatusUnchanged, Comparable: true, Complete: true, Before: before.Reference, After: after.Reference, Summary: Summary{Matched: 1}, Matched: []Match{{Before: component, After: component, LocationChange: false}}}
	initial, _ := json.Marshal([]Report{before, after})
	got, err := Compare(before, after)
	if err != nil || !reflect.DeepEqual(got, want) {
		t.Fatal("stress changed hardware continuity, fields or signed references", err, got)
	}
	final, _ := json.Marshal([]Report{before, after})
	if !bytes.Equal(initial, final) {
		t.Fatal("comparison mutated verified inputs")
	}
}

func TestCPUStressComparisonRevalidatesEachVerifiedSide(t *testing.T) {
	for _, side := range []string{"before", "after"} {
		t.Run(side, func(t *testing.T) {
			before, after := verifiedStressComparison(t, false), verifiedStressComparison(t, true)
			if got, err := Compare(before, after); err != nil || got.Status != StatusUnchanged || got.Summary.Matched != 1 {
				t.Fatal("positive comparison prerequisite", err)
			}
			target := &before
			if side == "after" {
				target = &after
			}
			target.Inventory.CoverageScope = ""
			target.Inventory.TestResults = []app.TestResult{{ID: "cpu.stress", Version: 1, Status: app.TestPass, Evidence: []byte(`{}`)}}
			if got, err := Compare(before, after); err == nil || !reflect.DeepEqual(got, Result{}) {
				t.Fatal("opaque stress passed comparison admission")
			}
		})
	}
}

